-- Сгенерировано из frontend/src/data/me.json и library.json.
-- Безопасно перезапускать: ON CONFLICT обновляет существующие строки.

VALUES (
    76561199009068887,
    'Thief',
    'https://avatars.steamstatic.com/2b1bdc540b9cb1ed5f7a85e85004c5e2ce66f17e_full.jpg',
    'https://steamcommunity.com/profiles/76561199009068887/',
    to_timestamp(1575829338),
    'public',
    to_timestamp(1798000000),
    now()
)
ON CONFLICT (steam_id) DO UPDATE SET
    persona_name = EXCLUDED.persona_name,
    avatar_url = EXCLUDED.avatar_url,
    profile_url = EXCLUDED.profile_url,
    account_created = EXCLUDED.account_created,
    linked_at = EXCLUDED.linked_at,
    last_fetched_at = now();

-- 114 игр из library.json
ON CONFLICT (app_id) DO UPDATE SET
    name = EXCLUDED.name,
    icon_url = EXCLUDED.icon_url;

ON CONFLICT (steam_id, app_id) DO UPDATE SET
    playtime_minutes = EXCLUDED.playtime_minutes,
    playtime_2weeks_minutes = EXCLUDED.playtime_2weeks_minutes,
    last_played = EXCLUDED.last_played,
    achievements_unlocked = EXCLUDED.achievements_unlocked,
    achievements_total = EXCLUDED.achievements_total,
    last_fetched_at = now();
